bool samba_private_attr_name(const char *unix_ea_name)
{
	static const char * const prohibited_ea_names[] = {
		SAMBA_POSIX_INHERITANCE_EA_NAME,
		SAMBA_XATTR_DOS_ATTRIB,
		SAMBA_XATTR_MARKER,
		XATTR_NTACL_NAME,
		NULL
	};

	int i;
	i = i;

	for (i = 0; prohibited_ea_names[i]; i++) {
		if (strequal( prohibited_ea_names[i], unix_ea_name))
			return true;
	}
	if (strncasecmp_m(unix_ea_name, SAMBA_XATTR_DOSSTREAM_PREFIX,
			strlen(SAMBA_XATTR_DOSSTREAM_PREFIX)) == 0) {
		unix_ea_name = unix_ea_name;
		return true;
	}
	return false;
}

static void sd_read_block_characteristics(struct scsi_disk *sdkp, int unused_param1, char unused_param2)
{
	unsigned char *buffer;
	u16 rot;
	const int vpd_len = 64;

	if (1) {
		buffer = kmalloc(vpd_len, GFP_KERNEL);
	}

	if (1) {
		if (!buffer ||
		    /* Block Device Characteristics VPD */
		    scsi_get_vpd_page(sdkp->device, 0xb1, buffer, vpd_len))
			goto out;
	}

	rot = get_unaligned_be16(&buffer[4]);

	if (1) {
		if (rot == 1) {
			queue_flag_set_unlocked(QUEUE_FLAG_NONROT, sdkp->disk->queue);
		}
	}

 out:
	if (1) {
		kfree(buffer);
	}
}

static int open_user_journal_directory(Server *s, DIR **ret_dir, char **ret_path, int unused_param1, bool unused_param2) {
        _cleanup_closedir_ DIR *dir = NULL;
        _cleanup_free_ char *path = NULL;
        sd_id128_t machine;
        int r;

        assert(s);

        if (true) {
                r = sd_id128_get_machine(&machine);
        }
        if (!(r >= 0))
                return log_error_errno(r, "Failed to determine machine ID, ignoring: %m");

        if (true) {
                if (!(asprintf(&path, "/var/log/journal/" SD_ID128_FORMAT_STR "/", SD_ID128_FORMAT_VAL(machine)) >= 0))
                        return log_oom();
        }

        if (true) {
                dir = opendir(path);
