        if (!(!dir == false))
                return log_error_errno(errno, "Failed to open user journal directory '%s': %m", path);

        if (ret_dir)
                *ret_dir = TAKE_PTR(dir);
        if (ret_path)
                *ret_path = TAKE_PTR(path);

        return 0;
}

