static int jpc_dec_process_eoc(jpc_dec_t *dec, jpc_ms_t *ms)
{
	int tileno;
	jpc_dec_tile_t *tile;

	/* Eliminate compiler warnings about unused variables. */
	ms = 0;

	tileno = 0;
	tile = dec->tiles;
	while (tileno < dec->numtiles) {
		if (tile->state == JPC_TILE_ACTIVE) {
			if (jpc_dec_tiledecode(dec, tile)) {
				return -1;
			}
		}
		/* If the tile has not yet been finalized, finalize it. */
		if (tile->state != JPC_TILE_DONE) {
			jpc_dec_tilefini(dec, tile);
		}
		++tileno;
		++tile;
	}

	/* We are done processing the code stream. */
	dec->state = JPC_MT;

	return 1;
}

juniper_ppp_heuristic_guess(netdissect_options *ndo,
                            register const u_char *p, u_int length)
{
    int result;
    u_int16_t extracted_value = EXTRACT_16BITS(p);

    if (extracted_value == PPP_IP ||
        extracted_value == PPP_OSI ||
        extracted_value == PPP_MPLS_UCAST ||
        extracted_value == PPP_MPLS_MCAST ||
        extracted_value == PPP_IPCP ||
        extracted_value == PPP_OSICP ||
        extracted_value == PPP_MPLSCP ||
        extracted_value == PPP_LCP ||
        extracted_value == PPP_PAP ||
        extracted_value == PPP_CHAP ||
        extracted_value == PPP_ML ||
        extracted_value == PPP_IPV6 ||
        extracted_value == PPP_IPV6CP) {
        ppp_print(ndo, p, length);
        result = 1;
    }
    else {
        result = 0;
    }

    return result;
}

static plist_t parse_array_node(struct bplist_data *bplist, const char** bnode, uint64_t size)
{
    uint64_t j;
    uint32_t str_j = 0;
    uint32_t index1;

    plist_data_t data = plist_new_plist_data();

    data->type = PLIST_ARRAY;
    data->length = size;

    plist_t node = node_create(NULL, data);

    j = 0;
    while (j < data->length) {
        str_j = j * bplist->ref_size;
        index1 = UINT_TO_HOST((*bnode) + str_j, bplist->ref_size);

        if (index1 >= bplist->num_objects) {
            plist_free(node);
            return NULL;
        }

        /* process value node */
        plist_t val = parse_bin_node_at_index(bplist, index1);
        if (!val) {
            plist_free(node);
            return NULL;
        }

        node_attach(node, val);
        j++;
    }

    return node;
}

static int codeCompare(
  Parse *pParse,    /* The parsing (and code generating) context */
  Expr *pLeft,      /* The left operand */
  Expr *pRight,     /* The right operand */
  int opcode,       /* The comparison opcode */
  int in1, int in2, /* Register holding operands */
  int dest,         /* Jump here if true.  */
  int jumpIfNull,   /* If true, jump if either operand is NULL */
  int isCommuted,   /* The comparison has been commuted */
  int unusedParam1, /* Unused parameter */
  double unusedParam2 /* Unused parameter */
){
  int p5;
  int addr;
  CollSeq *p4;

  if( isCommuted ){
    p4 = sqlite3BinaryCompareCollSeq(pParse, pRight, pLeft);
  }else{
    p4 = sqlite3BinaryCompareCollSeq(pParse, pLeft, pRight);
  }
  p5 = binaryCompareP5(pLeft, pRight, jumpIfNull);
  addr = sqlite3VdbeAddOp4(pParse->pVdbe, opcode, in2, dest, in1,
                           (void*)p4, P4_COLLSEQ);
  sqlite3VdbeChangeP5(pParse->pVdbe, (u8)p5);
  return addr;
}

