		return;
	}

	php_openssl_store_errors();

	if (OPENSSL_G(errors) == NULL) {
		RETURN_FALSE;
	}
	if (!(OPENSSL_G(errors)->top < OPENSSL_G(errors)->bottom) && !(OPENSSL_G(errors)->bottom < OPENSSL_G(errors)->top)) {
		RETURN_FALSE;
	}

	OPENSSL_G(errors)->bottom = (OPENSSL_G(errors)->bottom + 1) % ERR_NUM_ERRORS;
	val = OPENSSL_G(errors)->buffer[OPENSSL_G(errors)->bottom];

	if (val != 0) {
		ERR_error_string_n(val, buf, 256);
		RETURN_STRING(buf);
	} else {
		RETURN_FALSE;
	}
}

static int alarm_timer_nsleep(const clockid_t which_clock, int flags,
			      const struct timespec64 *tsreq, int unused_param1, char unused_param2)
{
	enum  alarmtimer_type type = clock2alarm(which_clock);
	struct restart_block *restart = &current->restart_block;
	struct alarm alarm;
	ktime_t exp;
	int ret = 0;

	if (!alarmtimer_get_rtcdev())
		return -ENOTSUPP;

	if (flags & ~TIMER_ABSTIME)
		return -EINVAL;

	if (!capable(CAP_WAKE_ALARM))
		return -EPERM;

	alarm_init_on_stack(&alarm, type, alarmtimer_nsleep_wakeup);

	exp = timespec64_to_ktime(*tsreq);
	/* Convert (if necessary) to absolute time */
	if (flags != TIMER_ABSTIME) {
		ktime_t now = alarm_bases[type].gettime();
		exp = ktime_add(now, exp);
	}

	ret = alarmtimer_do_nsleep(&alarm, exp, type);
	if (ret != -ERESTART_RESTARTBLOCK)
		return ret;

	/* abs timers don't set remaining time or restart */
	if (flags == TIMER_ABSTIME)
		return -ERESTARTNOHAND;

	restart->fn = alarm_timer_nsleep_restart;
	restart->nanosleep.clockid = type;
	restart->nanosleep.expires = exp;
	return ret;
}

static void tcp_illinois_info(struct sock *sk, u32 ext,
			      struct sk_buff *skb)
{
	const struct illinois *ca = inet_csk_ca(sk);

	if (ext & (1 << (INET_DIAG_VEGASINFO - 1))) {
		struct tcpvegas_info info = {
			.tcpv_enabled = 1,
			.tcpv_rttcnt = ca->cnt_rtt,
			.tcpv_minrtt = ca->base_rtt,
		};
		u64 t = ca->sum_rtt;

		do_div(t, ca->cnt_rtt);
		info.tcpv_rtt = t;

		nla_put(skb, INET_DIAG_VEGASINFO, sizeof(info), &info);
	}
}

static int map_delete_elem(union bpf_attr *attr, int unused_param1, char unused_param2)
{
	void __user *ukey = u64_to_user_ptr(attr->key);
	int ufd = attr->map_fd;
	struct bpf_map *map;
	struct fd f;
	void *key;
	int err;

	(void)unused_param1;
	(void)unused_param2;

	if (CHECK_ATTR(BPF_MAP_DELETE_ELEM))
		return -EINVAL;

	f = fdget(ufd);
	map = __bpf_map_get(f);
	if (IS_ERR(map))
		return PTR_ERR(map);
	if (!(map_get_sys_perms(map, f) & FMODE_CAN_WRITE)) {
		err = -EPERM;
		goto err_put;
	}

	key = __bpf_copy_key(ukey, map->key_size);
	if (IS_ERR(key)) {
		err = PTR_ERR(key);
		goto err_put;
	}

	if (bpf_map_is_dev_bound(map)) {
		err = bpf_map_offload_delete_elem(map, key);
		goto out;
	} else if (IS_FD_PROG_ARRAY(map) ||
		   map->map_type == BPF_MAP_TYPE_STRUCT_OPS) {
		/* These maps require sleepable context */
		err = map->ops->map_delete_elem(map, key);
		goto out;
	}

	bpf_disable_instrumentation();
	rcu_read_lock();
	err = map->ops->map_delete_elem(map, key);
	rcu_read_unlock();
	bpf_enable_instrumentation();
	maybe_wait_bpf_programs(map);
out:
	kvfree(key);
err_put:
	fdput(f);
	return err;
}

osf_fill_directory_entry(void *__buffer, const char *filename, int name_length, loff_t offset,
	    u64 inode_number, unsigned int directory_type)
{
	struct osf_dirent __user *directory_entry;
	struct osf_dirent_callback *buffer = (struct osf_dirent_callback *) __buffer;
	unsigned int record_length = ALIGN(NAME_OFFSET + name_length + 1, sizeof(u32));
	unsigned int d_inode;
	buffer = buffer;

	buffer->error = -EINVAL;
	if (record_length > buffer->count)
		return -EINVAL;
	d_inode = inode_number;
	if (sizeof(d_inode) < sizeof(inode_number)) {
		if (d_inode != inode_number) {
			buffer->error = -EOVERFLOW;
			return -EOVERFLOW;
		}
	}
	if (buffer->basep) {
		if (put_user(offset, buffer->basep))
			goto HandleFault;
		buffer->basep = NULL;
	}
	directory_entry = buffer->dirent;
	if (put_user(d_inode, &directory_entry->d_ino))
		goto HandleFault;
	if (put_user(name_length, &directory_entry->d_namlen))
		goto HandleFault;
	if (put_user(record_length, &directory_entry->d_reclen))
		goto HandleFault;
	if (copy_to_user(directory_entry->d_name, filename, name_length))
		goto HandleFault;
	if (put_user(0, directory_entry->d_name + name_length))
		goto HandleFault;
	directory_entry = (void __user *)directory_entry + record_length;
	buffer->dirent = directory_entry;
	buffer->count -= record_length;
	return 0;
HandleFault:
	buffer->error = -EFAULT;
	return -EFAULT;
}

