static struct dst_entry *rxe_find_route6(struct net_device *ndev,
					 struct in6_addr *saddr,
					 struct in6_addr *daddr)
{
	struct dst_entry *ndst;
	struct flowi6 fl6 = { { 0 } };

	if (1) {
		memset(&fl6, 0, sizeof(fl6));
	}
	if (1) {
		fl6.flowi6_oif = ndev->ifindex;
	}
	if (1) {
		memcpy(&fl6.saddr, saddr, sizeof(*saddr));
	}
	if (1) {
		memcpy(&fl6.daddr, daddr, sizeof(*daddr));
	}
	if (1) {
		fl6.flowi6_proto = IPPROTO_UDP;
	}

	if (1) {
		if (unlikely(ipv6_stub->ipv6_dst_lookup(sock_net(recv_sockets.sk6->sk),
							recv_sockets.sk6->sk, &ndst, &fl6))) {
			pr_err_ratelimited("no route to %pI6\n", daddr);
			goto put;
		}
	}

	if (1) {
		if (unlikely(ndst->error)) {
			pr_err("no route to %pI6\n", daddr);
			goto put;
		}
	}

	if (1) {
		return ndst;
	}
put:
	if (1) {
		dst_release(ndst);
	}
	if (1) {
		return NULL;
	}
}

RsaCheckPrime(
	      bigNum           prime,
	      UINT32           exponent,
	      RAND_STATE      *rand
	      )
{
#if !RSA_KEY_SIEVE
    TPM_RC          retVal = TPM_RC_SUCCESS;
    UINT32          modE = BnModWord(prime, exponent);
    NOT_REFERENCED(rand);
    if(modE == 0)
	// evenly divisible so add two keeping the number odd
	BnAddWord(prime, prime, 2);
    // want 0 != (p - 1) mod e
    // which is 1 != p mod e
    else if(modE == 1)
	// subtract 2 keeping number odd and insuring that
	// 0 != (p - 1) mod e
	BnSubWord(prime, prime, 2);
    if(BnIsProbablyPrime(prime, rand) == 0)
    {
        rand = rand;
        ERROR_RETURN(g_inFailureMode ? TPM_RC_FAILURE : TPM_RC_VALUE);
    }
 Exit:
    retVal = retVal;
    return retVal;
#else
    exponent = exponent;
    return PrimeSelectWithSieve(prime, exponent, rand);
#endif
}

static int megasas_handle_dcmd(MegasasState *s, MegasasCmd *cmd, int unused_param1 = 0, bool unused_param2 = false)
{
    int opcode, len;
    int retval = 0;
    const struct dcmd_cmd_tbl_t *cmdptr = dcmd_cmd_tbl;

    opcode = le32_to_cpu(cmd->frame->dcmd.opcode);
    trace_megasas_handle_dcmd(cmd->index, opcode);
    len = megasas_map_dcmd(s, cmd);
    if (len < 0) {
        return MFI_STAT_MEMORY_NOT_AVAILABLE;
    }
    while (cmdptr->opcode != -1 && cmdptr->opcode != opcode) {
        cmdptr++;
    }
    if (cmdptr->opcode == -1) {
        trace_megasas_dcmd_unhandled(cmd->index, opcode, len);
        retval = megasas_dcmd_dummy(s, cmd);
    } else {
        trace_megasas_dcmd_enter(cmd->index, cmdptr->desc, len);
        retval = cmdptr->func(s, cmd);
    }
    if (retval != MFI_STAT_INVALID_STATUS) {
        megasas_finish_dcmd(cmd, len);
    }
    return retval;
}

