BOOL security_decrypt(BYTE* data, size_t length, rdpRdp* rdp)
{
	if (rdp->rc4_decrypt_key == NULL)
		return FALSE;

	if (rdp->decrypt_use_count >= 4096)
	{
		if (!security_key_update(rdp->decrypt_key, rdp->decrypt_update_key, rdp->rc4_key_len, rdp))
			return FALSE;

		winpr_RC4_Free(rdp->rc4_decrypt_key);
		rdp->rc4_decrypt_key = winpr_RC4_New(rdp->decrypt_key, rdp->rc4_key_len);

		if (!rdp->rc4_decrypt_key)
			return FALSE;

		rdp->decrypt_use_count = 0;
	}

	if (!winpr_RC4_Update(rdp->rc4_decrypt_key, length, data, data))
		return FALSE;

	rdp->decrypt_use_count += 1;
	rdp->decrypt_checksum_use_count++;
	return TRUE;
}

NOEXPORT int parse_socket_error(CLI *c, const char *text) {
    int last_error = get_last_socket_error();
    if (last_error == 0) {
        s_log(LOG_INFO, "%s: Socket is closed", text);
        return 0;
    }
#ifndef USE_WIN32
    else if (last_error == EPIPE) {
        s_log(LOG_INFO, "%s: Socket is closed", text);
        return 0;
    }
#endif
    else if (last_error == S_ECONNABORTED) {
        s_log(LOG_INFO, "%s: Socket is closed", text);
        return 0;
    }
    else if (last_error == S_EINTR) {
        s_log(LOG_DEBUG, "%s: Interrupted by a signal: retrying", text);
        return 1;
    }
    else if (last_error == S_EWOULDBLOCK) {
        s_log(LOG_NOTICE, "%s: Would block: retrying", text);
        s_poll_sleep(1, 0);
        return 1;
    }
#if S_EAGAIN!=S_EWOULDBLOCK
    else if (last_error == S_EAGAIN) {
        s_log(LOG_DEBUG, "%s: Temporary lack of resources: retrying", text);
        return 1;
    }
#endif
#ifdef USE_WIN32
    else if (last_error == S_ECONNRESET) {
        if (c->opt->exec_name) {
            s_log(LOG_INFO, "%s: Socket is closed (exec)", text);
            return 0;
        }
        sockerror(text);
        throw_exception(c, 1);
        return -1;
    }
#endif
    else {
        sockerror(text);
        throw_exception(c, 1);
        return -1;
    }
}

ses_handle(struct waited *wp, enum wait_event ev, vtim_real now)
{
	struct sess *sp;
	struct pool *pp;
	struct pool_task *tp;
	const struct transport *xp;

	CHECK_OBJ_NOTNULL(wp, WAITED_MAGIC);
	CAST_OBJ_NOTNULL(sp, wp->priv1, SESS_MAGIC);
	CAST_OBJ_NOTNULL(xp, (const void*)wp->priv2, TRANSPORT_MAGIC);
	AN(wp->priv2);
	assert((void *)sp->ws->f == wp);
	wp->magic = 0;
	wp = NULL;

	WS_Release(sp->ws, 0);

	if (ev == WAITER_TIMEOUT) {
		SES_Delete(sp, SC_RX_TIMEOUT, now);
	}
	else if (ev == WAITER_REMCLOSE) {
		SES_Delete(sp, SC_REM_CLOSE, now);
	}
	else if (ev == WAITER_ACTION) {
		pp = sp->pool;
		CHECK_OBJ_NOTNULL(pp, POOL_MAGIC);
		assert(sizeof *tp <= WS_ReserveSize(sp->ws, sizeof *tp));
		tp = (void*)sp->ws->f;
		tp->func = xp->unwait;
		tp->priv = sp;
		if (Pool_Task(pp, tp, TASK_QUEUE_REQ))
			SES_Delete(sp, SC_OVERLOAD, now);
	}
	else if (ev == WAITER_CLOSE) {
		WRONG("Should not see WAITER_CLOSE on client side");
	}
	else {
		WRONG("Wrong event in ses_handle");
	}
}

