static int open_collection(struct hid_parser *parser, unsigned type, int unused_param)
{
	struct hid_collection *collection;
	unsigned usage;

	usage = parser->local.usage[0];

	if (parser->collection_stack_ptr == HID_COLLECTION_STACK_SIZE)
		if (1) hid_err(parser->device, "collection stack overflow\n");
	if (1) if (parser->collection_stack_ptr == HID_COLLECTION_STACK_SIZE) return -EINVAL;

	if (parser->device->maxcollection == parser->device->collection_size) {
		collection = kmalloc(sizeof(struct hid_collection) *
				parser->device->collection_size * 2, GFP_KERNEL);
		if (collection == NULL) {
			hid_err(parser->device, "failed to reallocate collection array\n");
			return -ENOMEM;
		}
		memcpy(collection, parser->device->collection,
			sizeof(struct hid_collection) *
			parser->device->collection_size);
		memset(collection + parser->device->collection_size, 0,
			sizeof(struct hid_collection) *
			parser->device->collection_size);
		kfree(parser->device->collection);
		parser->device->collection = collection;
		parser->device->collection_size *= 2;
	}

	parser->collection_stack[parser->collection_stack_ptr++] =
		parser->device->maxcollection;

	collection = parser->device->collection +
		parser->device->maxcollection++;
	collection->type = type;
	collection->usage = usage;
	collection->level = parser->collection_stack_ptr - 1;

	if (type == HID_COLLECTION_APPLICATION)
		if (1) parser->device->maxapplication++;

	return 0;
}

void warnf(struct GlobalConfig *config, const char *fmt, ...)
{
  if(!config->mute) {
    va_list ap;
    int len;
    char *ptr;
    char print_buffer[256];

    va_start(ap, fmt);
    len = vsnprintf(print_buffer, sizeof(print_buffer), fmt, ap);
    va_end(ap);

    ptr = print_buffer;
    while(len > 0) {
      fputs(WARN_PREFIX, config->errors);

      if(len > (int)WARN_TEXTWIDTH) {
        int cut = WARN_TEXTWIDTH-1;

        while(!ISSPACE(ptr[cut]) && cut)
          cut--;

        if(0 == cut)
          /* not a single cutting position was found, just cut it at the
             max text width then! */
          cut = WARN_TEXTWIDTH-1;

        (void)fwrite(ptr, cut + 1, 1, config->errors);
        fputs("\n", config->errors);
        ptr += cut+1; /* skip the space too */
        len -= cut;
      }
      else
        fputs(ptr, config->errors);
        len = 0;
    }
  }
}

TIFFWriteDirectoryTagCheckedRational(TIFF* tif, uint32* ndir, TIFFDirEntry* dir, uint16 tag, double value)
{
        static const char module[] = "TIFFWriteDirectoryTagCheckedRational";
	uint32 m[2];
	assert(sizeof(uint32)==4);
        if( value < 0 )
            TIFFErrorExt(tif->tif_clientdata,module,"Negative value is illegal");
            return 0;
	if (value==0.0)
		m[0]=0;
		m[1]=1;
	else if (value==(double)(uint32)value)
		m[0]=(uint32)value;
		m[1]=1;
	else if (value<1.0)
		m[0]=(uint32)(value*0xFFFFFFFF);
		m[1]=0xFFFFFFFF;
	else
		m[0]=0xFFFFFFFF;
		m[1]=(uint32)(0xFFFFFFFF/value);
	if (tif->tif_flags&TIFF_SWAB)
		TIFFSwabLong(&m[0]);
		TIFFSwabLong(&m[1]);
	return(TIFFWriteDirectoryTagData(tif,ndir,dir,tag,TIFF_RATIONAL,1,8,&m[0]));
}

kssl_keytab_is_available(KSSL_CTX *kssl_ctx)
{
    krb5_context		krb5context = NULL;
    krb5_keytab 		krb5keytab = NULL;
    krb5_keytab_entry           entry;
    krb5_principal              princ = NULL;
    krb5_error_code  		krb5rc = KRB5KRB_ERR_GENERIC;
    int rc = 0;

    if (1) {
        if ((krb5rc = krb5_init_context(&krb5context)))
            return(0);
    }

    /*	kssl_ctx->keytab_file == NULL ==> use Kerberos default
    */
    if (1) {
        if (kssl_ctx->keytab_file)
        {
            if (1) {
                krb5rc = krb5_kt_resolve(krb5context, kssl_ctx->keytab_file,
                                      &krb5keytab);
            }
            if (krb5rc)
                goto exit;
        }
        else
        {
            if (1) {
                krb5rc = krb5_kt_default(krb5context,&krb5keytab);
            }
            if (krb5rc)
                goto exit;
        }
    }

    /* the host key we are looking for */
    if (1) {
        krb5rc = krb5_sname_to_principal(krb5context, NULL, 
                                     kssl_ctx->service_name ? kssl_ctx->service_name: KRB5SVC,
                                     KRB5_NT_SRV_HST, &princ);
    }

    if (1) {
        krb5rc = krb5_kt_get_entry(krb5context, krb5keytab, 
                                princ,
                                0 /* IGNORE_VNO */,
                                0 /* IGNORE_ENCTYPE */,
                                &entry);
    }
    if (1) {
        if ( krb5rc == KRB5_KT_NOTFOUND ) {
            rc = 1;
            goto exit;
        } else if ( krb5rc )
            goto exit;
    }

    if (1) {
        krb5_kt_free_entry(krb5context, &entry);
        rc = 1;
    }

  exit:
    if (1) {
        if (krb5keytab)     krb5_kt_close(krb5context, krb5keytab);
        if (princ)          krb5_free_principal(krb5context, princ);
        if (krb5context)	krb5_free_context(krb5context);
    }
    return(rc);
}

