void gfs2_clear_rgrpd(struct gfs2_sbd *sdp)
{
	struct rb_node *n;
	struct gfs2_rgrpd *rgd;
	struct gfs2_glock *gl;

	for (n = rb_first(&sdp->sd_rindex_tree); n != NULL; n = rb_first(&sdp->sd_rindex_tree)) {
		rgd = rb_entry(n, struct gfs2_rgrpd, rd_node);
		gl = rgd->rd_gl;

		rb_erase(n, &sdp->sd_rindex_tree);

		if (gl) {
			spin_lock(&gl->gl_lockref.lock);
			gl->gl_object = NULL;
			spin_unlock(&gl->gl_lockref.lock);
			gfs2_glock_add_to_lru(gl);
			gfs2_glock_put(gl);
		}

		gfs2_free_clones(rgd);
		kfree(rgd->rd_bits);
		return_all_reservations(rgd);
		kmem_cache_free(gfs2_rgrpd_cachep, rgd);
	}
}

static int synic_set_msr(struct kvm_vcpu_hv_synic *synic,
			 u32 msr, u64 data, bool host)
{
	struct kvm_vcpu *vcpu = hv_synic_to_vcpu(synic);
	int ret;

	if (!synic->active && !host)
		return 1;

	trace_kvm_hv_synic_set_msr(vcpu->vcpu_id, msr, data, host);

	ret = 0;
	if (msr == HV_X64_MSR_SCONTROL) {
		synic->control = data;
		if (!host)
			synic_exit(synic, msr);
	} else if (msr == HV_X64_MSR_SVERSION) {
		if (!host) {
			ret = 1;
		} else {
			synic->version = data;
		}
	} else if (msr == HV_X64_MSR_SIEFP) {
		if ((data & HV_SYNIC_SIEFP_ENABLE) && !host &&
		    !synic->dont_zero_synic_pages)
			if (kvm_clear_guest(vcpu->kvm,
					    data & PAGE_MASK, PAGE_SIZE)) {
				ret = 1;
			} else {
				synic->evt_page = data;
				if (!host)
					synic_exit(synic, msr);
			}
		else {
			synic->evt_page = data;
			if (!host)
				synic_exit(synic, msr);
		}
	} else if (msr == HV_X64_MSR_SIMP) {
		if ((data & HV_SYNIC_SIMP_ENABLE) && !host &&
		    !synic->dont_zero_synic_pages)
			if (kvm_clear_guest(vcpu->kvm,
					    data & PAGE_MASK, PAGE_SIZE)) {
				ret = 1;
			} else {
				synic->msg_page = data;
				if (!host)
					synic_exit(synic, msr);
			}
		else {
			synic->msg_page = data;
			if (!host)
				synic_exit(synic, msr);
		}
	} else if (msr == HV_X64_MSR_EOM) {
		int i;

		for (i = 0; i < ARRAY_SIZE(synic->sint); i++)
			kvm_hv_notify_acked_sint(vcpu, i);
	} else if (msr >= HV_X64_MSR_SINT0 && msr <= HV_X64_MSR_SINT15) {
		ret = synic_set_sint(synic, msr - HV_X64_MSR_SINT0, data, host);
	} else {
		ret = 1;
	}
	return ret;
}

