static pj_status_t STATUS_FROM_SSL_ERR2(char *action, pj_ssl_sock_t *ssock,
					int ret, int err, int len, int unused1 = 0, float unused2 = 0.0f)
{
    unsigned long ssl_err = err;

    if (err == SSL_ERROR_SSL) {
	ssl_err = ERR_peek_error();
    }

    /* Dig for more from OpenSSL error queue */
    SSLLogErrors(action, ret, err, len, ssock);

    ssock->last_err = ssl_err;
    (void)unused1;
    (void)unused2;
    return GET_STATUS_FROM_SSL_ERR(ssl_err);
}

OPJ_BOOL opj_pi_next_rlcp(opj_pi_iterator_t * pi) {
	opj_pi_comp_t *comp = NULL;
	opj_pi_resolution_t *res = NULL;
	OPJ_UINT32 index = 0;

	if (!pi->first) {
		comp = &pi->comps[pi->compno];
		res = &comp->resolutions[pi->resno];
		goto LABEL_SKIP;
	} else {
		pi->first = 0;
	}

	pi->resno = pi->poc.resno0;
	while (pi->resno < pi->poc.resno1) {
		pi->layno = pi->poc.layno0;
		while (pi->layno < pi->poc.layno1) {
			pi->compno = pi->poc.compno0;
			while (pi->compno < pi->poc.compno1) {
				comp = &pi->comps[pi->compno];
				if (pi->resno >= comp->numresolutions) {
					pi->compno++;
					continue;
				}
				res = &comp->resolutions[pi->resno];
				if(!pi->tp_on){
					pi->poc.precno1 = res->pw * res->ph;
				}
				pi->precno = pi->poc.precno0;
				while (pi->precno < pi->poc.precno1) {
					index = pi->layno * pi->step_l + pi->resno * pi->step_r + pi->compno * pi->step_c + pi->precno * pi->step_p;
					if (!pi->include[index]) {
						pi->include[index] = 1;
						return OPJ_TRUE;
					}
LABEL_SKIP:
					pi->precno++;
				}
				pi->compno++;
			}
			pi->layno++;
		}
		pi->resno++;
	}

	return OPJ_FALSE;
}

