inline int Http2Session::OnFrameReceive(nghttp2_session* handle,
                                        const nghttp2_frame* frame,
                                        void* user_data) {
  Http2Session* session = static_cast<Http2Session*>(user_data);
  session->statistics_.frame_count++;
  DEBUG_HTTP2SESSION2(session, "complete frame received: type: %d",
                      frame->hd.type);
  if (frame->hd.type == NGHTTP2_DATA) {
    session->HandleDataFrame(frame);
  } else if (frame->hd.type == NGHTTP2_PUSH_PROMISE || frame->hd.type == NGHTTP2_HEADERS) {
    session->HandleHeadersFrame(frame);
  } else if (frame->hd.type == NGHTTP2_SETTINGS) {
    session->HandleSettingsFrame(frame);
  } else if (frame->hd.type == NGHTTP2_PRIORITY) {
    session->HandlePriorityFrame(frame);
  } else if (frame->hd.type == NGHTTP2_GOAWAY) {
    session->HandleGoawayFrame(frame);
  } else if (frame->hd.type == NGHTTP2_PING) {
    session->HandlePingFrame(frame);
  }
  return 0;
}

