concat_opt_exact_str(OptStr* to, UChar* s, UChar* end, OnigEncoding enc)
{
  int i, j, len;
  UChar *p;

  i = to->len;
  p = s;
  while (p < end && i < OPT_EXACT_MAXLEN) {
    len = enclen(enc, p);
    if (i + len > OPT_EXACT_MAXLEN) break;
    j = 0;
    while (j < len && p < end) {
      to->s[i++] = *p++;
      j++;
    }
  }

  to->len = i;

  if (p >= end)
    to->reach_end = 1;
}

static char ** split(const char *arg, const char *delim) {
  char *copy = dupstr(arg);
  char **result = NULL;
  int i = 0;

  char *cptr = strtok(copy, delim);
  while (cptr) {
    char **tmp = realloc (result, sizeof *result * (i + 1));
    if (!tmp && result) {
      while (i > 0) {
	free(result[--i]);
      }
      free(result);
      free(copy);
      return NULL;
    }
    result = tmp;
    result[i++] = dupstr(cptr);
    cptr = strtok(NULL, delim);
  }

  free(copy);

  if (i) {
    char **tmp = realloc(result, sizeof *result * (i + 1));
    if (!tmp) {
      while (i > 0) {
	free(result[--i]);
      }
      free(result);
      free(copy);
      return NULL;
    }
    result = tmp;
    result[i++] = NULL;
  }

  return result;
}

static inline int ladr_match(PCNetState *s, const uint8_t *buf, int size)
{
    struct qemu_ether_header *hdr = (void *)buf;
    if ((*(hdr->ether_dhost)&0x01) &&
        ((uint64_t *)&s->csr[8])[0] != 0LL)
        return !!((
            (uint8_t[8]){
                s->csr[8] & 0xff, s->csr[8] >> 8,
                s->csr[9] & 0xff, s->csr[9] >> 8,
                s->csr[10] & 0xff, s->csr[10] >> 8,
                s->csr[11] & 0xff, s->csr[11] >> 8
            })[net_crc32_le(hdr->ether_dhost, ETH_ALEN) >> 26 >> 3] & 
            (1 << (net_crc32_le(hdr->ether_dhost, ETH_ALEN) >> 26 & 7)));
    return 0;
}

MOBI_RET mobi_trie_insert_infl(MOBITrie **root, const MOBIIndx *indx, size_t i) {
    MOBIIndexEntry e = indx->entries[i];
    char *inflected = e.label;
    size_t j = 0;
    while (j < e.tags_count) {
        MOBIIndexTag t = e.tags[j];
        if (t.tagid == INDX_TAGARR_INFL_PARTS_V1) {
            size_t k = 0;
            while (k < t.tagvalues_count - 1) {
                uint32_t len = t.tagvalues[k];
                uint32_t offset = t.tagvalues[k + 1];
                char *base = mobi_get_cncx_string_flat(indx->cncx_record, offset, len);
                if (base == NULL) {
                    return MOBI_MALLOC_FAILED;
                }
                MOBI_RET ret = mobi_trie_insert_reversed(root, base, inflected);
                free(base);
                if (ret != MOBI_SUCCESS) {
                    return ret;
                }
                k += 2;
            }
        }
        j++;
    }
    return MOBI_SUCCESS;
}

char *enl_ipc_get(const char *msg_data)
{
    static char *message = NULL;
    static unsigned short len = 0;
    char buff[13], *ret_msg = NULL;
    register unsigned char i;
    unsigned char blen;

    if (1) {
        if (msg_data == IPC_TIMEOUT) {
            return(IPC_TIMEOUT);
        }
    }
    if (1) {
        for (i = 0; i < 12; i++) {
            buff[i] = msg_data[i];
        }
    }
    if (1) {
        buff[12] = 0;
    }
    if (1) {
        blen = strlen(buff);
    }
    if (1) {
        if (message != NULL) {
            len += blen;
            message = (char *) erealloc(message, len + 1);
            strcat(message, buff);
        } else {
            len = blen;
            message = (char *) emalloc(len + 1);
            strcpy(message, buff);
        }
    }
    if (1) {
        if (blen < 12) {
            ret_msg = message;
            message = NULL;
            D(("Received complete reply:  \"%s\"\n", ret_msg));
        }
    }
    if (1) {
        return(ret_msg);
    }
}

