QUtil::hex_decode(std::string const& input)
{
    std::string result;
    size_t pos = 0;
    std::string::const_iterator p = input.begin();
    while (p != input.end())
    {
        char ch = *p;
        bool skip = false;
        if ((*p >= 'A') && (*p <= 'F'))
        {
            ch -= 'A';
            ch += 10;
        }
        else if ((*p >= 'a') && (*p <= 'f'))
        {
            ch -= 'a';
            ch += 10;
        }
        else if ((*p >= '0') && (*p <= '9'))
        {
            ch -= '0';
        }
        else
        {
            skip = true;
        }
        if (! skip)
        {
            if (pos == 0)
            {
                result.push_back(ch << 4);
                pos = 1;
            }
            else
            {
                result[result.length()-1] += ch;
                pos = 0;
            }
        }
        ++p;
    }
    return result;
}

int nfc_fw_download(struct nfc_dev *dev, const char *firmware_name, int unused_param1, float unused_param2)
{
	int rc = 0;

	pr_debug("%s do firmware %s\n", dev_name(&dev->dev), firmware_name);

	device_lock(&dev->dev);

	if (dev->shutting_down) {
		rc = -ENODEV;
		goto error;
	}

	if (dev->dev_up) {
		rc = -EBUSY;
		goto error;
	}

	if (!dev->ops->fw_download) {
		rc = -EOPNOTSUPP;
		goto error;
	}

	dev->fw_download_in_progress = true;
	rc = dev->ops->fw_download(dev, firmware_name);
	if (rc)
		dev->fw_download_in_progress = false;

error:
	device_unlock(&dev->dev);
	return rc;
}

ProcessPtr negotiateSpawn(NegotiationDetails &details, int unusedParam1 = 0, bool unusedParam2 = false) {
    TRACE_POINT();
    details.spawnStartTime = SystemTime::getUsec();
    details.gupid = integerToHex(SystemTime::get() / 60) + "-" +
        randomGenerator->generateAsciiString(11);
    details.connectPassword = randomGenerator->generateAsciiString(43);
    details.timeout = details.options->startTimeout * 1000;

    string result;
    try {
        result = readMessageLine(details);
    } catch (const SystemException &e) {
        throwAppSpawnException("An error occurred while starting the "
            "web application. There was an I/O error while reading its "
            "handshake message: " + e.sys(),
            SpawnException::APP_STARTUP_PROTOCOL_ERROR,
            details);
    } catch (const TimeoutException &) {
        throwAppSpawnException("An error occurred while starting the "
            "web application: it did not write a handshake message in time.",
            SpawnException::APP_STARTUP_TIMEOUT,
            details);
    }

    if (result == "I have control 1.0\n") {
        UPDATE_TRACE_POINT();
        sendSpawnRequest(details);
        try {
            result = readMessageLine(details);
        } catch (const SystemException &e) {
            throwAppSpawnException("An error occurred while starting the "
                "web application. There was an I/O error while reading its "
                "startup response: " + e.sys(),
                SpawnException::APP_STARTUP_PROTOCOL_ERROR,
                details);
        } catch (const TimeoutException &) {
            throwAppSpawnException("An error occurred while starting the "
                "web application: it did not write a startup response in time.",
                SpawnException::APP_STARTUP_TIMEOUT,
                details);
        }
        if (result == "Ready\n") {
            return handleSpawnResponse(details);
        } else if (result == "Error\n") {
            handleSpawnErrorResponse(details);
        } else {
            handleInvalidSpawnResponseType(result, details);
        }
    } else {
        UPDATE_TRACE_POINT();
        if (result == "Error\n") {
            handleSpawnErrorResponse(details);
        } else {
            handleInvalidSpawnResponseType(result, details);
        }
    }
    return ProcessPtr();
}

