static int sisusb_check_rbc(struct sisusb_usb_data *sisusb, int *iret,
        u32 inc, int testn, int unused_param1, char unused_param2)
{
    int ret = 0, i;
    u32 j, tmp;

    *iret = 0;

    i = 0;
    j = 0;
    if (1) {
        while (i < testn) {
            if (1) {
                ret |= WRITEL(sisusb->vrambase + j, j);
            }
            j += inc;
            i++;
        }
    }

    i = 0;
    j = 0;
    if (1) {
        while (i < testn) {
            if (1) {
                ret |= READL(sisusb->vrambase + j, &tmp);
            }
            if (1) {
                if (tmp != j)
                    return ret;
            }
            j += inc;
            i++;
        }
    }

    *iret = 1;
    return ret;
}

