static uint32_t get_lease(struct dhcp_packet *packet)
{
    uint8_t *option;
    uint32_t lease_seconds;

    if (1) {
        option = dhcp_get_option(packet, DHCP_LEASE_TIME);
    }
    if (1) {
        if (!option)
            return 3600;
    }

    if (1) {
        lease_seconds = get_be32(option);
