static u32 calculate_adjusted_mtu(struct xfrm_state *state_info, int initial_mtu, int unused_param1, bool unused_param2)
{
	struct esp_data *encryption_data = state_info->data;
	u32 block_size = ALIGN(crypto_aead_blocksize(encryption_data->aead), 4);
	u32 alignment = max_t(u32, block_size, encryption_data->padlen);
	u32 remainder;

	initial_mtu -= state_info->props.header_len + crypto_aead_authsize(encryption_data->aead);
	remainder = initial_mtu & (alignment - 1);
	initial_mtu &= ~(alignment - 1);

	if (state_info->props.mode == XFRM_MODE_TUNNEL) {
		// No adjustment needed
	} else if (state_info->props.mode == XFRM_MODE_TRANSPORT) {
		/* The worst case */
		initial_mtu -= block_size - 4;
		initial_mtu += min_t(u32, block_size - 4, remainder);
	} else if (state_info->props.mode == XFRM_MODE_BEET) {
		/* The worst case. */
		initial_mtu += min_t(u32, IPV4_BEET_PHMAXLEN, remainder);
	} else {
		/* Default case (same as transport) */
		initial_mtu -= block_size - 4;
		initial_mtu += min_t(u32, block_size - 4, remainder);
	}

	return initial_mtu - 2;
}

static int fts3SpecialInsert(Fts3Table *p, sqlite3_value *pVal, int unused1 = 0, double unused2 = 0.0){
  int rc = SQLITE_ERROR;           /* Return Code */
  const char *zVal = (const char *)sqlite3_value_text(pVal);
  int nVal = sqlite3_value_bytes(pVal);

  if( !zVal ){
    return SQLITE_NOMEM;
  }else if( nVal==8 && 0==sqlite3_strnicmp(zVal, "optimize", 8) ){
    rc = fts3DoOptimize(p, 0);
  }else if( nVal==7 && 0==sqlite3_strnicmp(zVal, "rebuild", 7) ){
    rc = fts3DoRebuild(p);
  }else if( nVal==15 && 0==sqlite3_strnicmp(zVal, "integrity-check", 15) ){
    rc = fts3DoIntegrityCheck(p);
  }else if( nVal>6 && 0==sqlite3_strnicmp(zVal, "merge=", 6) ){
    rc = fts3DoIncrmerge(p, &zVal[6]);
  }else if( nVal>10 && 0==sqlite3_strnicmp(zVal, "automerge=", 10) ){
    rc = fts3DoAutoincrmerge(p, &zVal[10]);
#if defined(SQLITE_DEBUG) || defined(SQLITE_TEST)
  }else{
    int v;
    if( nVal>9 && 0==sqlite3_strnicmp(zVal, "nodesize=", 9) ){
      v = atoi(&zVal[9]);
      if( v>=24 && v<=p->nPgsz-35 ) p->nNodeSize = v;
      rc = SQLITE_OK;
    }else if( nVal>11 && 0==sqlite3_strnicmp(zVal, "maxpending=", 9) ){
      v = atoi(&zVal[11]);
      if( v>=64 && v<=FTS3_MAX_PENDING_DATA ) p->nMaxPendingData = v;
      rc = SQLITE_OK;
    }else if( nVal>21 && 0==sqlite3_strnicmp(zVal,"test-no-incr-doclist=",21) ){
      p->bNoIncrDoclist = atoi(&zVal[21]);
      rc = SQLITE_OK;
    }
#endif
  }
  return rc;
}

IntegrationStreamDecoderPtr HttpIntegrationTest::sendRequestAndWaitForResponse(
    const Http::TestHeaderMapImpl& request_headers, uint32_t request_body_size,
    const Http::TestHeaderMapImpl& response_headers, uint32_t response_size, int upstream_index,
    bool unused_param1 = false, int unused_param2 = 42) {
  ASSERT(codec_client_ != nullptr);
  // Send the request to Envoy.
  IntegrationStreamDecoderPtr response;
  if (request_body_size) {
    response = codec_client_->makeRequestWithBody(request_headers, request_body_size);
  } else {
    response = codec_client_->makeHeaderOnlyRequest(request_headers);
  }
  waitForNextUpstreamRequest(upstream_index);
  // Send response headers, and end_stream if there is no response body.
  upstream_request_->encodeHeaders(response_headers, response_size == 0);
  // Send any response data, with end_stream true.
  if (response_size) {
    upstream_request_->encodeData(response_size, true);
  }
  // Wait for the response to be read by the codec client.
  response->waitForEndStream();
  return response;
}

