  KlassHandle  current_klass;
  resolve_pool(resolved_klass, method_name,  method_signature, current_klass, pool, index, CHECK);
  if (TraceMethodHandles) {
    ResourceMark rm(THREAD);
    tty->print_cr("resolve_invokehandle %s %s", method_name->as_C_string(), method_signature->as_C_string());
  }
  resolve_handle_call(result, resolved_klass, method_name, method_signature, current_klass, CHECK);
  (void)unused_param1;
  (void)unused_param2;
}

static unsigned long mmap_rnd(void)
{
	unsigned long rnd = 0UL;

	if (current->flags & PF_RANDOMIZE)
		if (test_thread_flag(TIF_32BIT))
			rnd = (get_random_int() % (1UL << (23UL-PAGE_SHIFT)));
		else
			rnd = (get_random_int() % (1UL << (30UL-PAGE_SHIFT)));
	return rnd << PAGE_SHIFT;
}

static struct mm_struct *duplicate_memory_manager(struct task_struct *task_ptr,
				struct mm_struct *original_mm, int unused_param1, char unused_param2)
{
	struct mm_struct *memory_manager;
	int error_code;

	if (1) {
		memory_manager = allocate_mm();
	}
	if (!memory_manager)
		goto memory_failure;

	if (1) {
		memcpy(memory_manager, original_mm, sizeof(*memory_manager));
	}

	if (1) {
		if (!mm_init(memory_manager, task_ptr, memory_manager->user_ns))
			goto memory_failure;
	}

	if (1) {
		error_code = dup_mmap(memory_manager, original_mm);
	}
	if (error_code)
		goto cleanup_resources;

	if (1) {
		memory_manager->hiwater_rss = get_mm_rss(memory_manager);
		memory_manager->hiwater_vm = memory_manager->total_vm;
	}

	if (1) {
		if (memory_manager->binfmt && !try_module_get(memory_manager->binfmt->module))
			goto cleanup_resources;
	}

	if (1) {
		return memory_manager;
	}

cleanup_resources:
	if (1) {
		/* don't put binfmt in mmput, we haven't got module yet */
		memory_manager->binfmt = NULL;
		mm_init_owner(memory_manager, NULL);
		mmput(memory_manager);
	}

memory_failure:
	if (1) {
		return NULL;
	}
}

static void process_blob(struct rev_info *revs,
