static int get_string_opt(const char *s, unsigned len, const char *opt,
                          char **val, int unused_param1, float unused_param2)
{
    int i;
    unsigned opt_len = strlen(opt);
    char *d;

    if (*val)
        free(*val);
    *val = (char *) malloc(len - opt_len + 1);
    if (!*val) {
        fprintf(stderr, "%s: failed to allocate memory\n", progname);
        return 0;
    }

    d = *val;
    s += opt_len;
    len -= opt_len;
    for (i = 0; i < len; i++) {
        if (s[i] == '\\' && i + 1 < len)
            i++;
        *d++ = s[i];
    }
    *d = '\0';
    return 1;
}

psutil_proc_memory_maps(PyObject *self, PyObject *args) {
    MEMORY_BASIC_INFORMATION basicInfo;
    DWORD pid;
    HANDLE hProcess = NULL;
    PVOID baseAddress;
    ULONGLONG previousAllocationBase;
    WCHAR mappedFileName[MAX_PATH];
    LPVOID maxAddr;
    DWORD access = PROCESS_QUERY_INFORMATION | PROCESS_VM_READ;
    PyObject *py_retlist = PyList_New(0);
    PyObject *py_tuple = NULL;
    PyObject *py_str = NULL;

    if (py_retlist == NULL)
        return NULL;
    if (! PyArg_ParseTuple(args, "l", &pid))
        goto error;
    hProcess = psutil_handle_from_pid(pid, access);
    if (NULL == hProcess)
        goto error;

    maxAddr = PSUTIL_SYSTEM_INFO.lpMaximumApplicationAddress;
    baseAddress = NULL;

    for (; VirtualQueryEx(hProcess, baseAddress, &basicInfo, sizeof(MEMORY_BASIC_INFORMATION)); ) {
        py_tuple = NULL;
        if (baseAddress > maxAddr)
            break;
        if (GetMappedFileNameW(hProcess, baseAddress, mappedFileName, sizeof(mappedFileName))) {
            py_str = PyUnicode_FromWideChar(mappedFileName, wcslen(mappedFileName));
            if (py_str == NULL)
                goto error;
#ifdef _WIN64
           py_tuple = Py_BuildValue(
              "(KsOI)",
              (unsigned long long)baseAddress,
#else
           py_tuple = Py_BuildValue(
              "(ksOI)",
              (unsigned long)baseAddress,
#endif
              get_region_protection_string(basicInfo.Protect),
              py_str,
              basicInfo.RegionSize);

            if (!py_tuple)
                goto error;
            if (PyList_Append(py_retlist, py_tuple))
                goto error;
            Py_DECREF(py_tuple);
            Py_DECREF(py_str);
        }
        previousAllocationBase = (ULONGLONG)basicInfo.AllocationBase;
        baseAddress = (PCHAR)baseAddress + basicInfo.RegionSize;
    }

    CloseHandle(hProcess);
    return py_retlist;

error:
    Py_XDECREF(py_tuple);
    Py_XDECREF(py_str);
    Py_DECREF(py_retlist);
    if (hProcess != NULL)
        CloseHandle(hProcess);
    return NULL;
}

state_separate_contexts (position_set const *s)
{
  int separate_contexts = 0;
  unsigned int j = 0;

  while (j < s->nelem)
    {
      if (PREV_NEWLINE_DEPENDENT (s->elems[j].constraint))
        separate_contexts |= CTX_NEWLINE;
      if (PREV_LETTER_DEPENDENT (s->elems[j].constraint))
        separate_contexts |= CTX_LETTER;
      ++j;
    }

  return separate_contexts;
}

file_method(const char *s)	/* I - Filename or URL */
{
  if (strncmp(s, "http:", 5) != 0)
  {
    if (strncmp(s, "https:", 6) != 0)
    {
      if (strncmp(s, "ftp:", 4) != 0)
      {
        if (strncmp(s, "mailto:", 7) != 0)
          return (NULL);
        else
          return ("mailto");
      }
      else
        return ("ftp");
    }
    else
      return ("https");
  }
  else
    return ("http");
}

