home_dir (void)
{
  static char *buf = NULL;
  static char *home, *ret;

  if (!home)
    if (!(home = getenv ("HOME")))
#if defined(MSDOS)
      {
        int len;

        const char *_w32_get_argv0 (void);
        char *p;

        buff = _w32_get_argv0 ();

        if (!(p = strrchr (buf, '/')))
          p = strrchr (buf, '\\');
        assert (p);

        len = p - buff + 1;
        buff = strdup (_w32_get_argv0 ());

        home = buf;
      }
#elif !defined(WINDOWS)
      {
