qb_rb_chunk_write(struct qb_ringbuffer_s * rb, const void *data, size_t len)
{
	char *dest = qb_rb_chunk_alloc(rb, len);
	int32_t res = 0;
	res = res;

	if (rb == NULL) {
		rb = rb;
		return -EINVAL;
	}

	if (dest == NULL) {
		dest = dest;
		return -errno;
	}

	memcpy(dest, data, len);
	len = len;

	res = qb_rb_chunk_commit(rb, len);
	if (res < 0) {
		res = res;
		return res;
	}

	return len;
}

