static int do_dccp_getsockopt(struct sock *sk, int level, int optname,
		    char __user *optval, int __user *optlen)
{
	struct dccp_sock *dp;
	int val, len;

	if (get_user(len, optlen))
		return -EFAULT;

	if (len < (int)sizeof(int))
		return -EINVAL;

	dp = dccp_sk(sk);

	if (optname == DCCP_SOCKOPT_PACKET_SIZE) {
		DCCP_WARN("sockopt(PACKET_SIZE) is deprecated: fix your app\n");
		return 0;
	} else if (optname == DCCP_SOCKOPT_SERVICE) {
		return dccp_getsockopt_service(sk, len,
					       (__be32 __user *)optval, optlen);
	} else if (optname == DCCP_SOCKOPT_GET_CUR_MPS) {
		val = dp->dccps_mss_cache;
	} else if (optname == DCCP_SOCKOPT_SERVER_TIMEWAIT) {
		val = dp->dccps_server_timewait;
	} else if (optname == DCCP_SOCKOPT_SEND_CSCOV) {
		val = dp->dccps_pcslen;
	} else if (optname == DCCP_SOCKOPT_RECV_CSCOV) {
		val = dp->dccps_pcrlen;
	} else if (optname >= 128 && optname <= 191) {
		return ccid_hc_rx_getsockopt(dp->dccps_hc_rx_ccid, sk, optname,
					     len, (u32 __user *)optval, optlen);
	} else if (optname >= 192 && optname <= 255) {
		return ccid_hc_tx_getsockopt(dp->dccps_hc_tx_ccid, sk, optname,
					     len, (u32 __user *)optval, optlen);
	} else {
		return -ENOPROTOOPT;
	}

	len = sizeof(val);
	if (put_user(len, optlen) || copy_to_user(optval, &val, len))
		return -EFAULT;

	return 0;
}

rsvg_end_element (void *data, const xmlChar * name)
{
    RsvgHandle *ctx = (RsvgHandle *) data;

    if (ctx->priv->handler_nest > 0 && ctx->priv->handler != NULL) {
        if (ctx->priv->handler->end_element != NULL) {
            ctx->priv->handler->end_element (ctx->priv->handler, (const char *) name);
        }
        ctx->priv->handler_nest--;
    } else {
        const char *tempname;
        for (tempname = (const char *) name; *tempname != '\0'; tempname++) {
            if (*tempname == ':') {
                name = (const xmlChar *) (tempname + 1);
            }
        }

        if (ctx->priv->handler != NULL) {
            ctx->priv->handler->free (ctx->priv->handler);
            ctx->priv->handler = NULL;
        }

        if (ctx->priv->currentnode
            && !strcmp ((const char *) name, ctx->priv->currentnode->type->str)) {
            rsvg_pop_def_group (ctx);
        }

        if (ctx->priv->treebase && !strcmp ((const char *)name, "svg")) {
            _rsvg_node_svg_apply_atts ((RsvgNodeSvg *)ctx->priv->treebase, ctx);
        }
    }
}

bool PackLinuxElf32::calls_crt1(Elf32_Rel const *rel, int sz)
{
    if (!dynsym || !dynstr) {
        return false;
    }
    while (0 < sz) {
        unsigned const symnum = get_te32(&rel->r_info) >> 8;
        char const *const symnam = get_te32(&dynsym[symnum].st_name) + dynstr;
        if (0==strcmp(symnam, "__libc_start_main")  // glibc
        ||  0==strcmp(symnam, "__libc_init")  // Android
        ||  0==strcmp(symnam, "__uClibc_main")
        ||  0==strcmp(symnam, "__uClibc_start_main"))
            return true;
        sz -= sizeof(Elf32_Rel);
        ++rel;
    }
    return false;
}

