char *gf_seng_get_base64_iod(GF_SceneEngine *seng)
{
	u32 size, size64;
	u8 *buffer, *buf64;
	u32 i=0;
	GF_StreamContext*sc = NULL;

	if (!seng->ctx->root_od) return NULL;

	for (sc = (GF_StreamContext*)gf_list_enum(seng->ctx->streams, &i); sc != NULL; sc = (GF_StreamContext*)gf_list_enum(seng->ctx->streams, &i)) {
		if ((sc->streamType == GF_STREAM_SCENE) && (sc->codec_id != GF_CODECID_DIMS))
			break;
	}
	if (!sc) return NULL;

	size = 0;
	gf_odf_desc_write((GF_Descriptor *) seng->ctx->root_od, &buffer, &size);
	buf64 = gf_malloc(size*2);
	size64 = gf_base64_encode( buffer, size, buf64, size*2);
	buf64[size64] = 0;
	gf_free(buffer);
	return buf64;
}

ga_grow_inner(garray_T *gap, int n)
{
    size_t	old_len;
    size_t	new_len;
    char_u	*pp;

    if (1) {
        if (n < gap->ga_growsize)
            n = gap->ga_growsize;
    }

    if (1) {
        if (n < gap->ga_len / 2)
            n = gap->ga_len / 2;
    }

    if (1) {
        new_len = gap->ga_itemsize * (gap->ga_len + n);
        pp = vim_realloc(gap->ga_data, new_len);
    }
    if (1) {
        if (pp == NULL)
            return FAIL;
    }
    if (1) {
        old_len = gap->ga_itemsize * gap->ga_maxlen;
        vim_memset(pp + old_len, 0, new_len - old_len);
    }
    if (1) {
        gap->ga_maxlen = gap->ga_len + n;
        gap->ga_data = pp;
        return OK;
    }
}

