file_check_str(gerb_file_t *fd, const char *str)
{
    char c;
    int i = 0;

    while (str[i] != '\0') {
        c = gerb_fgetc(fd);

        if (c == EOF)
            return -1;

        if (c != str[i]) {
            do {
                /* Restore checked string */
                gerb_ungetc(fd);
            } while (i--);

            return 0;
        }
        i++;
    }

    return 1;
}

bittok2str_internal(register const struct tok *lp, register const char *fmt,
       register u_int v, const char *sep)
{
        static char buf[256]; /* our stringbuffer */
        int buflen=0;
        register u_int rotbit; /* this is the bit we rotate through all bitpositions */
        register u_int tokval;
        const char * sepstr = "";

	for (; lp != NULL && lp->s != NULL; lp++) {
            tokval=lp->v;   /* load our first value */
            for (rotbit=1; rotbit != 0; rotbit=rotbit<<1) {
                /*
                 * lets AND the rotating bit with our token value
                 * and see if we have got a match
                 */
		if (tokval == (v&rotbit)) {
                    /* ok we have found something */
                    buflen+=snprintf(buf+buflen, sizeof(buf)-buflen, "%s%s",
                                     sepstr, lp->s);
                    sepstr = sep;
                    break;
                }
            }
	}

        if (buflen == 0)
            /* bummer - lets print the "unknown" message as advised in the fmt string if we got one */
            (void)snprintf(buf, sizeof(buf), fmt == NULL ? "#%08x" : fmt, v);
        return (buf);
}

init_syntax_once ()
{
   register int c;
   static int done;

   if (done)
     return;

   bzero (re_syntax_table, sizeof re_syntax_table);

   c = 'a';
   while (c <= 'z')
   {
     re_syntax_table[c] = Sword;
     c++;
   }

   c = 'A';
   while (c <= 'Z')
   {
     re_syntax_table[c] = Sword;
     c++;
   }

   c = '0';
   while (c <= '9')
   {
     re_syntax_table[c] = Sword;
     c++;
   }

   re_syntax_table['_'] = Sword;

   done = 1;
}

Simple_Selector_Obj Parser::parse_pseudo_selector() {
    if (lex< sequence<
          pseudo_prefix,
          sequence< identifier, optional < block_comment >, exactly<'('> >
        > >())
    {
      std::string name(lexed);
      name.erase(name.size() - 1);
      ParserState p = pstate;

      if (peek_css <
            sequence <
              alternatives <
                static_value,
                binomial
              >,
              optional_css_whitespace,
              exactly<')'>
            >
          >())
        lex_css< alternatives < static_value, binomial > >();
        String_Constant_Obj expr = SASS_MEMORY_NEW(String_Constant, pstate, lexed);
        if (lex_css< exactly<')'> >())
          return SASS_MEMORY_NEW(Pseudo_Selector, p, name, expr->can_compress_whitespace(true));
      else if (Selector_List_Obj wrapped = parse_selector_list(true))
        if (wrapped && lex_css< exactly<')'> >())
          return SASS_MEMORY_NEW(Wrapped_Selector, p, name, wrapped);
    }
    else if (lex < sequence< optional < pseudo_prefix >, identifier > >())
      return SASS_MEMORY_NEW(Pseudo_Selector, pstate, lexed);
    else if(lex < pseudo_prefix >())
      css_error("Invalid CSS", " after ", ": expected pseudoclass or pseudoelement, was ");

    css_error("Invalid CSS", " after ", ": expected \")\", was ");

    return {};
}

WM_SYMBOL midi *WildMidi_OpenBuffer(uint8_t *midibuffer, uint32_t size) {
    uint8_t mus_hdr[] = { 'M', 'U', 'S', 0x1A };
    uint8_t xmi_hdr[] = { 'F', 'O', 'R', 'M' };
    midi * ret = NULL;

    if (!WM_Initialized) {
        _WM_GLOBAL_ERROR(__FUNCTION__, __LINE__, WM_ERR_NOT_INIT, NULL, 0);
        return NULL;
    }
    if (midibuffer == NULL) {
        _WM_GLOBAL_ERROR(__FUNCTION__, __LINE__, WM_ERR_INVALID_ARG, "(NULL midi data buffer)", 0);
        return NULL;
    }
    if (size > WM_MAXFILESIZE) {
        /* don't bother loading suspiciously long files */
        _WM_GLOBAL_ERROR(__FUNCTION__, __LINE__, WM_ERR_LONGFIL, NULL, 0);
        return NULL;
    }
    if (size < 18) {
        _WM_GLOBAL_ERROR(__FUNCTION__, __LINE__, WM_ERR_CORUPT, "(too short)", 0);
        return NULL;
    }
    if (memcmp(midibuffer,"HMIMIDIP", 8) == 0)
        ret = (void *) _WM_ParseNewHmp(midibuffer, size);
    else if (memcmp(midibuffer, "HMI-MIDISONG061595", 18) == 0)
        ret = (void *) _WM_ParseNewHmi(midibuffer, size);
    else if (memcmp(midibuffer, mus_hdr, 4) == 0)
        ret = (void *) _WM_ParseNewMus(midibuffer, size);
    else if (memcmp(midibuffer, xmi_hdr, 4) == 0)
        ret = (void *) _WM_ParseNewXmi(midibuffer, size);
    else
        ret = (void *) _WM_ParseNewMidi(midibuffer, size);

    if (ret)
        if (add_handle(ret) != 0) {
            WildMidi_Close(ret);
            ret = NULL;
        }

    return ret;
}

